const root=()=>document.getElementById('effectRoot');
export function shouldCelebrateOnce(key,storage=globalThis.localStorage){const k=`outageMoneySeen:${key}`;if(storage?.getItem(k))return false;storage?.setItem(k,'1');return true}
export function runMoneyRain({durationMs=2400}={}){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=root();for(let i=0;i<30;i++){const n=document.createElement('span');n.className='money-piece';n.textContent=i%3?'£':'💷';n.style.left=`${Math.random()*96}%`;n.style.animationDelay=`${Math.random()*.7}s`;n.style.animationDuration=`${1.6+Math.random()*1.4}s`;r.appendChild(n);setTimeout(()=>n.remove(),durationMs+1000)}}
function overlay(kicker,value,title,duration=2400){const el=document.createElement('div');el.className='celebration';el.innerHTML=`<div class="celebration-card"><div class="celebration-kicker">${kicker}</div><div class="celebration-value">${value}</div><div class="celebration-title">${title}</div></div>`;root().appendChild(el);setTimeout(()=>el.remove(),duration)}
export function showMilestoneCelebration(m){overlay('Milestone unlocked',new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(m.amount),m.amount===5000?'£5K GREMLIN':'KEEP GOING');runMoneyRain({})}
export function showShiftComplete(period,netAmount){overlay('ANOTHER ONE BITES THE DUST','DONE',`${((netAmount)||0).toLocaleString('en-GB',{style:'currency',currency:'GBP'})} NET`,2100)}
export function showBossDefeated(period,netAmount){overlay('BOSS DEFEATED',period.date,'SOLD ANOTHER WEEKEND',2800);runMoneyRain({durationMs:2700})}
export function bossModel(period,nowMs,core){if(!period)return null;const start=core.ukDateTimeMs(period.date,period.start),end=core.ukDateTimeMs(period.date,period.end);if(nowMs<start||nowMs>=end)return null;const total=end-start,elapsed=nowMs-start,remain=end-nowMs;const day=new Date(`${period.date}T12:00:00Z`).getUTCDay();return{title:day===6?'SATURDAY BOSS':'SUNDAY BOSS',progress:Math.max(0,Math.min(1,elapsed/total)),hp:Math.ceil(remain/1000),remainingLabel:`${Math.floor(remain/3600000)}h ${Math.floor((remain%3600000)/60000)}m`,earned:core.earnedForPeriod(period,nowMs)}}
